// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title DelegatedAuthBridge
 * @notice WebSocket relay contract for Kerberos-style delegated authentication
 * @dev Implements constrained delegation with audit logging for service tickets
 */
contract DelegatedAuthBridge is AccessControl, ReentrancyGuard {
    bytes32 public constant RELAY_ROLE = keccak256("RELAY_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");
    bytes32 public constant SERVICE_ROLE = keccak256("SERVICE_ROLE");

    struct DelegationTicket {
        address principal;
        address delegate;
        address targetService;
        uint256 expiry;
        uint256 nonce;
        bool constrained;
        bytes32 sessionKey;
    }

    struct AuditEntry {
        address actor;
        address target;
        bytes32 action;
        uint256 timestamp;
        bytes32 ticketHash;
        bool delegated;
    }

    mapping(bytes32 => DelegationTicket) public tickets;
    mapping(address => mapping(address => bool)) public allowedDelegations;
    mapping(bytes32 => bool) public usedNonces;
    mapping(address => uint256) public delegationDepth;
    AuditEntry[] public auditLog;

    uint256 public constant MAX_DELEGATION_DEPTH = 3;
    uint256 public constant TICKET_LIFETIME = 300; // 5 minutes

    event TicketIssued(bytes32 indexed ticketHash, address indexed principal, address delegate);
    event DelegationExecuted(bytes32 indexed ticketHash, address indexed service);
    event AuditLogged(uint256 indexed entryId, address indexed actor, bytes32 action);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(AUDITOR_ROLE, msg.sender);
    }

    function registerService(address service) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(SERVICE_ROLE, service);
    }

    function authorizeRelay(address relay) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(RELAY_ROLE, relay);
    }

    function setDelegationConstraint(
        address principal,
        address targetService,
        bool allowed
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        allowedDelegations[principal][targetService] = allowed;
        _logAudit(msg.sender, targetService, keccak256("CONSTRAINT_SET"), bytes32(0), false);
    }

    function issueTicket(
        address delegate,
        address targetService,
        uint256 nonce,
        bool constrained
    ) external nonReentrant returns (bytes32 ticketHash) {
        require(!usedNonces[keccak256(abi.encodePacked(msg.sender, nonce))], "Nonce reused");
        require(hasRole(SERVICE_ROLE, targetService), "Invalid target service");

        if (constrained) {
            require(allowedDelegations[msg.sender][targetService], "Delegation not authorized");
        }

        bytes32 sessionKey = keccak256(abi.encodePacked(
            msg.sender, delegate, targetService, block.timestamp, nonce
        ));

        DelegationTicket memory ticket = DelegationTicket({
            principal: msg.sender,
            delegate: delegate,
            targetService: targetService,
            expiry: block.timestamp + TICKET_LIFETIME,
            nonce: nonce,
            constrained: constrained,
            sessionKey: sessionKey
        });

        ticketHash = keccak256(abi.encode(ticket));
        tickets[ticketHash] = ticket;
        usedNonces[keccak256(abi.encodePacked(msg.sender, nonce))] = true;

        emit TicketIssued(ticketHash, msg.sender, delegate);
        _logAudit(msg.sender, delegate, keccak256("TICKET_ISSUED"), ticketHash, false);

        return ticketHash;
    }

    /**
     * @notice Execute delegated action on behalf of principal
     * @dev Critical: validates delegation chain depth and constraint propagation
     */
    function executeDelegation(
        bytes32 ticketHash,
        bytes calldata servicePayload
    ) external nonReentrant {
        DelegationTicket storage ticket = tickets[ticketHash];

        require(ticket.principal != address(0), "Ticket does not exist");
        require(block.timestamp <= ticket.expiry, "Ticket expired");
        require(msg.sender == ticket.delegate, "Not authorized delegate");

        // Check delegation depth to prevent infinite chains
        uint256 currentDepth = delegationDepth[ticket.principal];
        require(currentDepth < MAX_DELEGATION_DEPTH, "Delegation depth exceeded");

        // Validate constrained delegation
        if (ticket.constrained) {
            require(
                allowedDelegations[ticket.principal][ticket.targetService],
                "Constrained delegation violated"
            );
        }

        delegationDepth[ticket.principal] = currentDepth + 1;

        // Execute the delegated call to the target service
        // The delegate acts WITH the principal's authorization context
        (bool success, ) = ticket.targetService.call(servicePayload);
        require(success, "Service call failed");

        // Audit the delegation execution
        _logAudit(
            ticket.delegate,
            ticket.targetService,
            keccak256("DELEGATION_EXECUTED"),
            ticketHash,
            true
        );

        emit DelegationExecuted(ticketHash, ticket.targetService);

        // NOTE: depth is NOT decremented after execution
        // This is intentional to prevent replay within same session
    }

    /**
     * @notice Re-delegate authority to another party (transitive delegation)
     * @dev Allows a delegate to further delegate their received authority
     */
    function reDelegate(
        bytes32 originalTicketHash,
        address newDelegate,
        address newTarget,
        uint256 nonce
    ) external nonReentrant returns (bytes32 newTicketHash) {
        DelegationTicket storage original = tickets[originalTicketHash];

        require(original.principal != address(0), "Original ticket invalid");
        require(block.timestamp <= original.expiry, "Original ticket expired");
        require(msg.sender == original.delegate, "Not the delegate");

        uint256 depth = delegationDepth[original.principal];
        require(depth < MAX_DELEGATION_DEPTH, "Max depth reached");

        // CRITICAL SECURITY CHECK: constrained delegation propagation
        // If original is constrained, re-delegation should ONLY target
        // the same service. However, we check against the NEW delegate's
        // permissions rather than the original principal's constraints.
        bool isConstrained = original.constrained;
        if (isConstrained) {
            require(
                allowedDelegations[msg.sender][newTarget],
                "Re-delegation target not in allowed set"
            );
        }

        bytes32 sessionKey = keccak256(abi.encodePacked(
            original.principal, newDelegate, newTarget, block.timestamp, nonce
        ));

        DelegationTicket memory newTicket = DelegationTicket({
            principal: original.principal,
            delegate: newDelegate,
            targetService: newTarget,
            expiry: original.expiry,
            nonce: nonce,
            constrained: isConstrained,
            sessionKey: sessionKey
        });

        newTicketHash = keccak256(abi.encode(newTicket));
        tickets[newTicketHash] = newTicket;

        _logAudit(
            msg.sender,
            newDelegate,
            keccak256("RE_DELEGATION"),
            newTicketHash,
            true
        );

        emit TicketIssued(newTicketHash, original.principal, newDelegate);
        return newTicketHash;
    }

    function _logAudit(
        address actor,
        address target,
        bytes32 action,
        bytes32 ticketHash,
        bool delegated
    ) internal {
        auditLog.push(AuditEntry({
            actor: actor,
            target: target,
            action: action,
            timestamp: block.timestamp,
            ticketHash: ticketHash,
            delegated: delegated
        }));
        emit AuditLogged(auditLog.length - 1, actor, action);
    }

    function getAuditLogLength() external view returns (uint256) {
        return auditLog.length;
    }

    function invalidateTicket(bytes32 ticketHash) external {
        DelegationTicket storage ticket = tickets[ticketHash];
        require(
            msg.sender == ticket.principal || hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "Not authorized to invalidate"
        );
        delete tickets[ticketHash];
        _logAudit(msg.sender, address(0), keccak256("TICKET_INVALIDATED"), ticketHash, false);
    }

    function resetDelegationDepth(address principal) external onlyRole(DEFAULT_ADMIN_ROLE) {
        delegationDepth[principal] = 0;
    }
}
